import{_ as e,c as r,o as s,a2 as a}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Formats pris en charge","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/formats.md","filePath":"fr/guide/formats.md","lastUpdated":1793163976000}'),n={name:"fr/guide/formats.md"};function i(l,t,o,d,c,g){return s(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="formats-pris-en-charge" tabindex="-1">Formats pris en charge <a class="header-anchor" href="#formats-pris-en-charge" aria-label="Permalink to &quot;Formats pris en charge&quot;">​</a></h1><p>NueZip prend en charge un large éventail de formats d&#39;archives en lecture et en écriture. Voici la matrice complète de compatibilité des formats.</p><h2 id="matrice-des-formats" tabindex="-1">Matrice des formats <a class="header-anchor" href="#matrice-des-formats" aria-label="Permalink to &quot;Matrice des formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th style="text-align:center;">Lecture</th><th style="text-align:center;">Écriture (Compression)</th><th style="text-align:center;">Chiffrement</th><th style="text-align:center;">Multi-volumes</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (lecture)</td><td style="text-align:center;">✅ (lecture)</td></tr></tbody></table><blockquote><p><strong>Remarque</strong> : La compression RAR n&#39;est pas prise en charge en raison de restrictions de licence. NueZip peut lire les archives RAR, y compris les archives RAR multi-volumes et chiffrées.</p></blockquote><h2 id="details-des-formats" tabindex="-1">Détails des formats <a class="header-anchor" href="#details-des-formats" aria-label="Permalink to &quot;Détails des formats&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>Compression</strong> : Store, Deflate, Deflate64, BZIP2, LZMA, PPMd</li><li><strong>Chiffrement</strong> : AES-256 (recommandé), ZipCrypto (hérité)</li><li><strong>Prise en charge des volumes</strong> : Archives fractionnées multi-volumes (<code>.zip.001</code>, <code>.zip.002</code>, ...)</li><li><strong>Idéal pour</strong> : Compatibilité universelle entre plates-formes</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>Compression</strong> : LZMA2 (par défaut), LZMA, PPMd, BZIP2, Deflate</li><li><strong>Chiffrement</strong> : AES-256</li><li><strong>Prise en charge des volumes</strong> : Archives fractionnées multi-volumes</li><li><strong>Idéal pour</strong> : Taux de compression maximal</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>Compression</strong> : Non compressé, ou combiné avec GZIP/BZIP2/XZ/Zstandard</li><li><strong>Idéal pour</strong> : Archives Unix/Linux, préservation des permissions de fichiers</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li>Formats de compression <strong>autonomes</strong> (fichier unique, sans regroupement d&#39;archive)</li><li>Souvent utilisés en combinaison avec TAR (<code>.tar.gz</code>, <code>.tar.xz</code>, <code>.tar.zst</code>)</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>Prise en charge en lecture</strong> : RAR4, RAR5, multi-volumes, chiffré</li><li><strong>Réparation</strong> : Enregistrement de récupération et reconstruction</li><li><strong>Écriture</strong> : Non pris en charge</li></ul><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li><strong>Pour partager avec d&#39;autres</strong> : Utilisez <strong>ZIP</strong> — c&#39;est le format le plus largement compatible</li><li><strong>Pour l&#39;archivage personnel</strong> : Utilisez <strong>7-Zip</strong> — meilleurs taux de compression, économise l&#39;espace disque</li><li><strong>Pour les fichiers volumineux</strong> : Utilisez <strong>Split ZIP</strong> ou <strong>Split 7-Zip</strong> pour les diviser en volumes gérables</li><li><strong>Pour les données sensibles</strong> : Activez toujours le <strong>chiffrement AES-256</strong> avec un mot de passe robuste</li></ul>',18)])])}const h=e(n,[["render",i]]);export{m as __pageData,h as default};
